package ncasa.shoppinglist.application;
import java.time.Clock;import java.util.*;import ncasa.shoppinglist.application.port.out.*;import ncasa.shoppinglist.domain.*;
public final class UpdateShoppingListUseCase{private final ShoppingListRepository lists;private final ShoppingListHouseholdAccessPort access;private final CalendarEntryReferencePort calendar;private final Clock clock;public UpdateShoppingListUseCase(ShoppingListRepository l,ShoppingListHouseholdAccessPort a,CalendarEntryReferencePort c,Clock k){lists=l;access=a;calendar=c;clock=k;}public ShoppingList execute(Long actor,UUID household,UUID id,long version,String name,UUID series){access.getContext(household,actor);var list=GetShoppingListUseCase.load(lists,id,household);checkVersion(list,version);var n=ShoppingListName.of(name);if(lists.existsActiveName(household,n.normalized(),id))throw new ShoppingListConflictException("Shopping list name already exists");if(series!=null){if(!calendar.activeSeriesExists(household,series))throw new ShoppingListConflictException("Calendar series is not active");lists.findActiveByCalendarSeries(series).filter(x->!x.id().equals(id)).ifPresent(x->{throw new ShoppingListConflictException("Calendar series already has a shopping list");});list.linkCalendar(series,clock.instant());}else list.unlinkCalendar(clock.instant());list.rename(n.value(),clock.instant());return lists.save(list);}static void checkVersion(ShoppingList l,long v){if(l.version()!=v)throw new ShoppingListConflictException("Shopping list changed concurrently");}}
